                            let block_first = target_boxes.first().unwrap_or(first);
                            let block_last = target_boxes.last().unwrap_or(last);
                            let direction = doc.node(target).style.direction;
                            let left = if direction == Direction::Rtl {
                                last.0.left
                            } else {
                                first.0.left
                            };
