                    && child_style.effective_border_top() == 0
                    && child_style.effective_border_bottom() == 0
                    && resolve_margin_or_padding(&child_style.padding_top, column_width)
                        == LayoutUnit::zero()
                    && resolve_margin_or_padding(&child_style.padding_bottom, column_width)
                        == LayoutUnit::zero();
